                                            ))}
                                        </div>
                                    )}
                                </div>
                            )}

                        </Card>
                    ))}
                </div>
            )}

            {/* Payment Modal */}
            {paymentModalOpen && selectedLoan && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
                    <Card className="w-full max-w-md p-6 bg-white dark:bg-slate-900">
                        <h2 className="text-xl font-bold mb-4">Make a Payment</h2>
                        <div className="space-y-4">
                            <div>
                                <p className="text-sm text-slate-500">Loan</p>
                                <p className="font-medium">{selectedLoan.type} ({selectedLoan.id})</p>
                            </div>
                            <div>
                                <p className="text-sm text-slate-500">Remaining Balance</p>
                                <p className="font-medium">LKR {formatNumber(selectedLoan.balance)}</p>
                            </div>
                            <div>
                                <Input 
                                    label="Payment Amount (LKR)" 
                                    type="number" 
                                    value={paymentAmount} 
                                    onChange={(e) => setPaymentAmount(e.target.value)}
                                    max={selectedLoan.balance}
                                />
                            </div>

                            {/* Dummy Credit Card Info */}
                            <div className="pt-4 border-t">
                                <p className="text-sm font-medium mb-2">Payment Details (Mock)</p>
                                <Input label="Card Number" placeholder="**** **** **** 4242" defaultValue="4242 4242 4242 4242" />
                            </div>

                            <div className="flex gap-3 justify-end mt-6">
                                <Button variant="ghost" onClick={() => setPaymentModalOpen(false)}>Cancel</Button>
                                <Button onClick={submitPayment} disabled={isProcessing || !paymentAmount || parseFloat(paymentAmount) <= 0}>
                                    {isProcessing ? 'Processing...' : 'Confirm Payment'}
                                </Button>
                            </div>
                        </div>
                    </Card>
                </div>
            )}
        </div>
    );
};

import { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { Card } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Badge } from '@/components/ui/Badge';
import { ArrowLeft, CheckCircle, FileText, Heart, Info, ShieldCheck, TrendingUp, XCircle } from 'lucide-react';
import { Doughnut } from 'react-chartjs-2';
import { formatNumber } from '@/utils/formatCurrency';
import {
    Chart as ChartJS,
    ArcElement,
    Tooltip,
    Legend
} from 'chart.js';

ChartJS.register(ArcElement, Tooltip, Legend);

interface RiskFactor {
    label: string;
    score: string;
    color: string;
    desc: string;
}

interface RiskAssessmentData {
    overallRiskScore: number;
    riskCategory: string;
    approvalProbability: number;
    approvalCategory: string;
    dti: number;
    dtiCategory: string;
    factors: RiskFactor[];
    insights: string[];
    alerts: Array<{ title: string; desc: string }>;
}

interface EligibilityResult {
    eligible: boolean;
    verdict: string;
    verdictColor: string;
    eligibilityScore: number;
    approvalProbability: number;
    estimatedEMI: number;
    dti: number;
    dtiCategory: string;
    lti: number;
    maxRecommendedLoan: number;
    documentBonus: number;
    strengths: RiskFactor[];
    improvements: RiskFactor[];
    insights: string[];
    alerts: Array<{ title: string; desc: string }>;
}

interface ApplicationRecord {
    id: string;
    status: string;
    loanAmount: string | number;
    loanPurpose: string;
    eligibilityResult?: EligibilityResult;
    eligibilityCheckedAt?: string;
    documents?: Array<{ _id?: string; fileName: string; fileType: string; status: string }>;
}

const getStatusVariant = (status: string): 'success' | 'warning' | 'error' | 'info' => (
    (status === 'Approved' || status === 'Manager Approved')
        ? 'success'
        : (status === 'Rejected' || status === 'Manager Rejected')
            ? 'error'
            : status === 'Needs Info'
                ? 'warning'
                : 'info'
);

const getVerdictVariant = (verdict?: string): 'default' | 'success' | 'warning' | 'error' => {
    if (!verdict) return 'default';
    if (verdict === 'Likely Eligible') return 'success';
    if (verdict === 'Conditionally Eligible') return 'warning';
    return 'error';
};

export const RiskResult = () => {
    const navigate = useNavigate();
    const { id } = useParams();
    const [riskData, setRiskData] = useState<RiskAssessmentData | null>(null);
    const [application, setApplication] = useState<ApplicationRecord | null>(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        const fetchRiskData = async () => {
            try {
                const [riskRes, applicationsRes] = await Promise.all([
                    fetch(`http://localhost:5000/api/applications/${id}/risk`),
                    fetch('http://localhost:5000/api/applications/my-applications')
                ]);

                const riskPayload = await riskRes.json();
                if (riskPayload.status === 'success') {
                    setRiskData(riskPayload.data);
                } else {
                    setError(riskPayload.message || 'Failed to fetch assessment');
                }

                if (applicationsRes.ok) {
                    const applications = await applicationsRes.json();
                    const currentApplication = applications.find((entry: ApplicationRecord) => entry.id === id);
                    setApplication(currentApplication || null);
                }
            } catch (err) {
                setError('Error connecting to Risk Engine');
            } finally {
                setLoading(false);
            }
        };

        if (id && id !== 'System-Mock') {
            void fetchRiskData();
        } else {
            setTimeout(() => {
                setRiskData({
                    overallRiskScore: 15,
                    riskCategory: 'Low Risk',
                    approvalProbability: 85,
                    approvalCategory: 'Highly Recommended',
                    dti: 28,
                    dtiCategory: 'Low',
                    factors: [
                        { label: 'Payment History', score: 'Excellent', color: 'text-green-600', desc: 'No missed payments' },
                        { label: 'Debt-to-Income', score: 'Excellent', color: 'text-green-600', desc: 'Healthy balance of income to debts' }
                    ],
                    insights: ['Applicant income stability is good.'],
                    alerts: []
                });
                setLoading(false);
            }, 800);
        }
    }, [id]);

    if (loading) {
        return (
            <div className="flex flex-col items-center justify-center p-12 space-y-4">
                <div className="w-12 h-12 border-4 border-primary/30 border-t-primary rounded-full animate-spin"></div>
                <p className="text-gray-500 font-medium">Analyzing your loan application...</p>
            </div>
        );
    }

    if (error) {
        return (
            <div className="p-8 text-center text-red-500 bg-red-50 dark:bg-red-900/20 rounded-xl border border-red-200">
                <Info className="w-8 h-8 mx-auto mb-2 text-red-400" />
                <p className="font-semibold">{error}</p>
                <Button variant="outline" className="mt-4" onClick={() => navigate('/customer/loans')}>Return to My Loans</Button>
            </div>
        );
    }

    if (!riskData) return null;

    const isGood = riskData.approvalProbability >= 70;
    const isModerate = riskData.approvalProbability >= 40 && riskData.approvalProbability < 70;

    const statusColor = isGood ? 'text-green-600 dark:text-green-400' : isModerate ? 'text-yellow-600 dark:text-yellow-400' : 'text-red-600 dark:text-red-400';
    const bgStatusColor = isGood ? 'bg-green-100 dark:bg-green-900/30' : isModerate ? 'bg-yellow-100 dark:bg-yellow-900/30' : 'bg-red-100 dark:bg-red-900/30';

    const probabilityData = {
        labels: ['Approval Probability', 'Remaining'],
        datasets: [{
            data: [riskData.approvalProbability, 100 - riskData.approvalProbability],
            backgroundColor: [isGood ? '#10b981' : isModerate ? '#f59e0b' : '#ef4444', 'rgba(200, 200, 200, 0.2)'],
            borderWidth: 0,
            circumference: 270,
            rotation: 225,
        }]
    };

    return (
        <div className="space-y-6 animate-fade-in text-light-text-primary dark:text-dark-text-primary max-w-5xl mx-auto">
            <div className="flex items-center justify-between">
                <div>
                    <Button
                        variant="ghost"
                        className="mb-2 pl-0 hover:bg-transparent hover:text-primary"
                        leftIcon={<ArrowLeft className="w-4 h-4" />}
                        onClick={() => navigate('/customer/loans')}
                    >
                        Back to My Loans
                    </Button>
                    <h1 className="text-2xl font-bold text-gray-800 dark:text-white flex items-center gap-2">
                        <ShieldCheck className="w-6 h-6 text-primary" />
                        Application Result - {id}
                    </h1>
                    <p className="text-sm text-gray-500 mt-1">Detailed risk analysis and uploaded document validation for your application.</p>
                </div>
            </div>

            {application && (
                <>
                    {application.documents && application.documents.length > 0 && (
                        <Card className="p-5">
                            <h3 className="text-base font-semibold mb-4">Uploaded Documents</h3>
                            <div className="space-y-3">
                                {application.documents.map((doc, idx) => (
                                    <div key={doc._id || `${doc.fileName}-${idx}`} className="flex flex-col gap-3 rounded-lg border border-slate-200 dark:border-slate-700 p-3 sm:flex-row sm:items-center sm:justify-between">
                                        <div className="flex items-center gap-3">
                                            <FileText className="w-5 h-5 text-slate-400" />
                                            <div>
                                                <p className="text-sm font-medium text-light-text-primary dark:text-dark-text-primary">{doc.fileName}</p>
                                                <p className="text-xs text-slate-500">{doc.fileType}</p>
                                            </div>
                                        </div>
                                        {doc.status === 'Invalid' ? (
                                            <Badge variant="error" className="bg-red-500 text-white font-bold px-3 py-1 flex items-center gap-1 shadow-sm ring-2 ring-red-500 ring-offset-1">
                                                <XCircle className="w-4 h-4" /> Invalid by System
                                            </Badge>
                                        ) : doc.status === 'Valid' ? (
                                            <Badge variant="success" className="bg-green-100 text-green-700 font-bold px-3 py-1 flex items-center gap-1">
                                                <CheckCircle className="w-4 h-4" /> Valid by System
                                            </Badge>
                                        ) : (
                                            <Badge variant="warning">{doc.status}</Badge>
                                        )}
                                    </div>
                                ))}
                            </div>
                        </Card>
                    )}

                    {application.eligibilityResult ? (
                        <>
                            <div className="flex flex-col gap-4 md:flex-row md:items-start md:justify-between p-5 rounded-xl border border-slate-200 dark:border-slate-700 bg-linear-to-br from-slate-50 to-white dark:from-slate-800/70 dark:to-slate-900">
                                <div>
                                    <p className="text-sm text-slate-500">Loan Purpose</p>
                                    <h2 className="text-2xl font-bold text-light-text-primary dark:text-dark-text-primary mt-1">
                                        {application.loanPurpose}
                                    </h2>
                                    <div className="mt-3 flex flex-wrap items-center gap-2">
                                        <Badge variant={getStatusVariant(application.status)}>{application.status}</Badge>
                                        <Badge variant={getVerdictVariant(application.eligibilityResult.verdict)}>
                                            {application.eligibilityResult.verdict}
                                        </Badge>
                                    </div>
                                    {application.eligibilityCheckedAt && (
                                        <p className="text-xs text-slate-500 mt-3">
                                            Eligibility checked on {new Date(application.eligibilityCheckedAt).toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' })}
                                        </p>
                                    )}
                                </div>
                                <div className="text-left md:text-right">
                                    <p className="text-sm text-slate-500">Requested Amount</p>
                                    <p className="text-2xl font-bold text-light-text-primary dark:text-dark-text-primary">
                                        LKR {formatNumber(Number(application.loanAmount))}
                                    </p>
                                </div>
                            </div>

                            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                                <Card className="p-4">
                                    <p className="text-xs uppercase tracking-wide text-slate-500">Eligibility Score</p>
                                    <p className="mt-2 text-2xl font-bold">{application.eligibilityResult.eligibilityScore}/100</p>
                                </Card>
                                <Card className="p-4">
                                    <p className="text-xs uppercase tracking-wide text-slate-500">Approval Probability</p>
                                    <p className="mt-2 text-2xl font-bold">{application.eligibilityResult.approvalProbability}%</p>
                                </Card>
                                <Card className="p-4">
                                    <p className="text-xs uppercase tracking-wide text-slate-500">Estimated EMI</p>
                                    <p className="mt-2 text-2xl font-bold">LKR {formatNumber(application.eligibilityResult.estimatedEMI)}</p>
                                </Card>
                                <Card className="p-4">
                                    <p className="text-xs uppercase tracking-wide text-slate-500">Debt-to-Income</p>
                                    <p className="mt-2 text-2xl font-bold">{application.eligibilityResult.dti}%</p>
                                    <p className="text-xs text-slate-500 mt-1">{application.eligibilityResult.dtiCategory}</p>
                                </Card>
                            </div>
                        </>
                    ) : (
                        <Card className="p-5">
                            <p className="text-sm text-slate-600 dark:text-slate-300">
                                This application does not have a stored eligibility result yet, but the risk analysis below is available.
                            </p>
                        </Card>
                    )}
                </>
            )}

            <Card className="overflow-hidden border-0 shadow-lg bg-linear-to-br from-white to-gray-50 dark:from-dark-bg-secondary dark:to-gray-900">
                <div className="grid grid-cols-1 md:grid-cols-2 p-8 gap-8 items-center">
                    <div className="space-y-6">
                        <div>
                            <span className={`inline-block px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wider ${bgStatusColor} ${statusColor} mb-4`}>
                                {isGood ? 'Looks Great!' : isModerate ? 'Needs Attention' : 'Action Required'}
                            </span>
                            <h2 className="text-3xl font-bold text-gray-900 dark:text-white leading-tight">
                                Your application has a {riskData.approvalProbability}% chance of approval.
                            </h2>
                            <p className="mt-4 text-gray-600 dark:text-gray-400">
                                This estimate is based on our AI engine analyzing your profile, debt-to-income ratio, and requested loan amount.
                                {isGood ? ' You are in a fantastic position to secure this loan!' : ' Read the tips below to see how you can improve your chances.'}
                            </p>
                        </div>

                        <div className="grid grid-cols-2 gap-4">
                            <div className="bg-white dark:bg-gray-800 p-4 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
                                <p className="text-xs text-gray-500 uppercase tracking-wide font-medium">Debt-to-Income</p>
                                <p className="text-xl font-bold text-gray-900 dark:text-white mt-1">{riskData.dti}%</p>
                            </div>
                            <div className="bg-white dark:bg-gray-800 p-4 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
                                <p className="text-xs text-gray-500 uppercase tracking-wide font-medium">Risk Tier</p>
                                <p className={`text-xl font-bold mt-1 ${statusColor}`}>{riskData.riskCategory.replace(' Risk', '')}</p>
                            </div>
                        </div>
                    </div>

                    <div className="relative h-64 flex justify-center items-center">
                        <div className="absolute inset-0 flex flex-col items-center justify-center pt-8">
                            <span className={`text-4xl font-extrabold ${statusColor}`}>{riskData.approvalProbability}%</span>
                            <span className="text-sm text-gray-500 font-medium">Match</span>
                        </div>
                        <Doughnut data={probabilityData} options={{ maintainAspectRatio: false, cutout: '80%', plugins: { tooltip: { enabled: false }, legend: { display: false } } }} />
                    </div>
                </div>
            </Card>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <Card className="p-6">
                    <div className="flex items-center gap-2 mb-6">
                        <div className="p-2 bg-green-100 dark:bg-green-900/30 rounded-lg">
                            <Heart className="w-5 h-5 text-green-600 dark:text-green-400" />
                        </div>
                        <h3 className="text-lg font-bold text-gray-800 dark:text-white">Profile Strengths</h3>
                    </div>

                    <ul className="space-y-4">
                        {riskData.factors.filter((factor) => factor.color.includes('green') || factor.color.includes('blue')).length > 0 ? (
                            riskData.factors
                                .filter((factor) => factor.color.includes('green') || factor.color.includes('blue'))
                                .map((factor, i) => (
                                    <li key={i} className="flex gap-3 items-start">
                                        <CheckCircle className="w-5 h-5 text-green-500 flex-shrink-0 mt-0.5" />
                                        <div>
                                            <p className="font-semibold text-gray-800 dark:text-gray-200">{factor.label}</p>
                                            <p className="text-sm text-gray-600 dark:text-gray-400 mt-1">{factor.desc}</p>
                                        </div>
                                    </li>
                                ))
                        ) : (
                            <p className="text-sm text-gray-500 italic">No significant strengths identified yet. Keep building your profile!</p>
                        )}
                    </ul>
                </Card>

                <Card className="p-6">
                    <div className="flex items-center gap-2 mb-6">
                        <div className="p-2 bg-yellow-100 dark:bg-yellow-900/30 rounded-lg">
                            <TrendingUp className="w-5 h-5 text-yellow-600 dark:text-yellow-400" />
                        </div>
                        <h3 className="text-lg font-bold text-gray-800 dark:text-white">Tips for Improvement</h3>
                    </div>

                    <ul className="space-y-4">
                        {riskData.factors.filter((factor) => factor.color.includes('yellow') || factor.color.includes('red')).length > 0 ? (
                            riskData.factors
                                .filter((factor) => factor.color.includes('yellow') || factor.color.includes('red'))
                                .map((factor, i) => (
                                    <li key={i} className="flex gap-3 items-start p-3 bg-gray-50 dark:bg-gray-800/50 rounded-lg border border-gray-100 dark:border-gray-700">
                                        <Info className="w-5 h-5 text-yellow-500 flex-shrink-0 mt-0.5" />
                                        <div>
                                            <p className="font-semibold text-gray-800 dark:text-gray-200">{factor.label}</p>
                                            <p className="text-sm text-gray-600 dark:text-gray-400 mt-1">{factor.desc}</p>
                                        </div>
                                    </li>
                                ))
                        ) : (
                            <div className="flex flex-col items-center justify-center p-4 text-center space-y-2">
                                <div className="p-3 bg-green-50 dark:bg-green-900/20 rounded-full">
                                    <CheckCircle className="w-6 h-6 text-green-500" />
                                </div>
                                <p className="text-sm text-gray-600 dark:text-gray-400 font-medium">Your profile is in top shape! No major red flags detected.</p>
                            </div>
                        )}
                    </ul>
                </Card>
            </div>

            <div className="text-center pt-4">
                <Button size="lg" className="px-12" onClick={() => navigate('/customer/loans')}>
                    Understood, Return to Loans
                </Button>
            </div>
        </div>
    );
};

import { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { Card } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { CheckCircle, XCircle, Download, FileText, ArrowLeft, Loader2, Info } from 'lucide-react';
import { useToast } from '@/components/ui/Toast';
import { formatNumber } from '@/utils/formatCurrency';

interface RiskSummary {
    overallRiskScore: number;
    riskCategory: string;
    approvalProbability: number;
    approvalCategory: string;
    dti: number;
    dtiCategory: string;
}

export const ApplicationVerification = () => {
    const navigate = useNavigate();
    const { id } = useParams();
    const { showToast } = useToast();

    const [app, setApp] = useState<any>(null);
    const [riskSummary, setRiskSummary] = useState<RiskSummary | null>(null);
    const [loading, setLoading] = useState(true);
    const [actionLoading, setActionLoading] = useState(false);

    useEffect(() => {
        const fetchAppAndRisk = async () => {
            try {
                const [appRes, riskRes] = await Promise.all([
                    fetch(`http://localhost:5000/api/officer/applications/${id}`),
                    fetch(`http://localhost:5000/api/applications/${id}/risk`)
                ]);

                if (appRes.ok) {
                    setApp(await appRes.json());
                } else {
                    showToast('Application not found', 'error');
                }

                if (riskRes.ok) {
                    const riskPayload = await riskRes.json();
                    if (riskPayload.status === 'success') {
                        setRiskSummary(riskPayload.data);
                    }
                }
            } catch (err) {
                console.error("Error fetching application:", err);
                showToast('Failed to load application', 'error');
            } finally {
                setLoading(false);
            }
        };
        if (id) {
            fetchAppAndRisk();
        }
    }, [id, showToast]);

    const handleStatusUpdate = async (status: string) => {
        setActionLoading(true);
        try {
            const res = await fetch(`http://localhost:5000/api/officer/applications/${id}/status`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ status })
            });
            const data = await res.json();

            if (res.ok) {
                showToast(`Application successfully updated to ${data.application.status}`, 'success');
                setApp(data.application); // Update local state to reflect new status
            } else {
                showToast(data.message || 'Failed to update application', 'error');
            }
        } catch (error) {
            console.error('Status update failed:', error);
            showToast('Network error while updating status', 'error');
        } finally {
            setActionLoading(false);
        }
    };

    const handleDownload = (doc: any) => {
        try {
            const dataParts = doc.data.split(',');
            const base64Data = dataParts.length > 1 ? dataParts[1] : dataParts[0];
            const binaryData = atob(base64Data);
            const arrayBuffer = new Uint8Array(binaryData.length);
            for (let i = 0; i < binaryData.length; i++) {
                arrayBuffer[i] = binaryData.charCodeAt(i);
            }
            const blob = new Blob([arrayBuffer], { type: doc.fileType });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = doc.fileName;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
            showToast(`Successfully downloaded: ${doc.fileName}`, 'success');
        } catch (e) {
            showToast('Failed to download document', 'error');
        }
    };

    if (loading) return <div className="p-8 text-center text-gray-500 flex justify-center items-center gap-2"><Loader2 className="animate-spin w-5 h-5"/> Loading application...</div>;
    if (!app) return <div className="p-8 text-center text-red-500">Failed to retrieve application.</div>;

    const statusColors: Record<string, string> = {
        'Approved': 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400',
        'Rejected': 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-400',
        'Manager Rejected': 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-400',
        'Manager Review': 'bg-purple-100 text-purple-800 dark:bg-purple-900/30 dark:text-purple-400',
        'Needs Info': 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-400',
        'Pending': 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400'
    };

    const riskColors: Record<string, string> = {
        'Low Risk': 'text-green-500',
        'Medium Risk': 'text-yellow-500',
        'High Risk': 'text-red-500'
    };

    return (
        <div className="space-y-6 animate-fade-in text-light-text-primary dark:text-dark-text-primary">
            {/* Header */}
            <div className="flex justify-between items-end">
                <div>
                    <Button
                        variant="ghost"
                        className="mb-2 pl-0 hover:bg-transparent hover:text-primary"
                        leftIcon={<ArrowLeft className="w-4 h-4" />}
                        onClick={() => navigate(-1)}
                    >
                        Back
                    </Button>
                    <h1 className="text-xl font-medium text-gray-600 dark:text-gray-300">Review Loan Application</h1>
                    <p className="text-sm text-gray-500 mt-1">Application ID: <span className="text-gray-700 dark:text-gray-200 font-medium">#{app.id}</span></p>
                </div>
                <div>
                    <span className={`px-3 py-1 rounded-full text-xs font-semibold ${statusColors[app.status] || statusColors['Pending']}`}>
                        {app.status}
                    </span>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Main Content - Left Column (2/3) */}
                <div className="lg:col-span-2 space-y-6">

                    {/* Applicant Information */}
                    <Card className="p-6">
                        <h2 className="text-base font-medium text-gray-700 dark:text-gray-200 mb-6">Applicant Information</h2>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-y-6 gap-x-12">
                            <div>
                                <p className="text-xs text-gray-500 mb-1">Full Name</p>
                                <p className="text-sm font-medium">{app.fullName}</p>
                            </div>
                            <div>
                                <p className="text-xs text-gray-500 mb-1">NIC / Passport</p>
                                <p className="text-sm font-medium">{app.nic}</p>
                            </div>
                            <div>
                                <p className="text-xs text-gray-500 mb-1">Email</p>
                                <p className="text-sm font-medium">{app.email || 'N/A'}</p>
                            </div>
                            <div>
                                <p className="text-xs text-gray-500 mb-1">Phone</p>
                                <p className="text-sm font-medium">{app.contactNumber}</p>
                            </div>
                            <div className="md:col-span-2">
                                <p className="text-xs text-gray-500 mb-1">Address</p>
                                <p className="text-sm font-medium">{app.address}</p>
                            </div>
                            <div>
                                <p className="text-xs text-gray-500 mb-1">Employment Status</p>
                                <p className="text-sm font-medium">{app.employmentType}</p>
                            </div>
                            <div>
                                <p className="text-xs text-gray-500 mb-1">Employer</p>
                                <p className="text-sm font-medium">{app.employerName}</p>
                            </div>
                        </div>
                    </Card>

                    {/* Financial Information */}
                    <Card className="p-6">
                        <h2 className="text-base font-medium text-gray-700 dark:text-gray-200 mb-6">Financial Information</h2>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-y-6 gap-x-12">
                            <div>
                                <p className="text-xs text-gray-500 mb-1">Gross Monthly Income</p>
                                <p className="text-sm font-medium">LKR {formatNumber(app.grossMonthlyIncome)}</p>
                            </div>
                            <div>
                                <p className="text-xs text-gray-500 mb-1">Net Monthly Income</p>
                                <p className="text-sm font-medium">LKR {formatNumber(app.netMonthlyIncome)}</p>
                            </div>
                            <div>
                                <p className="text-xs text-gray-500 mb-1">Existing Loan Commitments</p>
                                <p className="text-sm font-medium">LKR {formatNumber(app.existingLoanCommitments) || 0}</p>
                            </div>
                            <div>
                                <p className="text-xs text-gray-500 mb-1">Service Period</p>
                                <p className="text-sm font-medium">{app.servicePeriod || 'N/A'}</p>
                            </div>
                        </div>
                    </Card>

                    {/* Requested Loan Details */}
                    <Card className="p-6">
                        <h2 className="text-base font-medium text-gray-700 dark:text-gray-200 mb-6">Requested Loan Details</h2>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-y-6 gap-x-12">
                            <div>
                                <p className="text-xs text-gray-500 mb-1">Loan Type</p>
                                <p className="text-sm font-medium">{app.loanType}</p>
                            </div>
                            <div>
                                <p className="text-xs text-gray-500 mb-1">Requested Amount</p>
                                <p className="text-sm font-medium">LKR {formatNumber(app.loanAmount)}</p>
                            </div>
                            <div>
                                <p className="text-xs text-gray-500 mb-1">Duration</p>
                                <p className="text-sm font-medium">{app.tenure} months</p>
                            </div>
                            <div>
                                <p className="text-xs text-gray-500 mb-1">Loan Purpose</p>
                                <p className="text-sm font-medium">{app.loanPurpose}</p>
                            </div>
                        </div>
                    </Card>

                    {/* Uploaded Documents */}
                    <Card className="p-6">
                        <h2 className="text-base font-medium text-gray-700 dark:text-gray-200 mb-6">Uploaded Documents</h2>
                        <div className="space-y-3">
                            {app.documents && app.documents.length > 0 ? app.documents.map((doc: any) => (
                                <div key={doc._id} className="flex flex-col gap-3 p-3 border border-gray-200 dark:border-gray-700 rounded-md">
                                    <div className="flex items-center justify-between">
                                        <div className="flex items-center gap-3">
                                            <FileText className="w-5 h-5 text-gray-400" />
                                            <span className="text-sm text-gray-700 dark:text-gray-300 truncate max-w-[200px]" title={doc.fileName}>{doc.fileName}</span>
                                            {doc.status === 'Invalid' ? (
                                                <span className="px-3 py-1 flex items-center gap-1 rounded bg-red-500 text-white text-xs font-bold shadow-sm ring-2 ring-red-500 ring-offset-1"><XCircle className="w-4 h-4" /> Invalid by System</span>
                                            ) : doc.status === 'Valid' ? (
                                                <span className="px-3 py-1 flex items-center gap-1 rounded bg-green-100 text-green-700 text-xs font-bold"><CheckCircle className="w-4 h-4"/> Valid by System</span>
                                            ) : (
                                                <span className="px-3 py-1 rounded bg-yellow-100 text-yellow-700 text-xs font-semibold">{doc.status}</span>
                                            )}
                                        </div>
                                        <Button variant="outline" size="sm" leftIcon={<Download className="w-4 h-4" />} onClick={() => handleDownload(doc)}>
                                            Download
                                        </Button>
                                    </div>
                                </div>
                            )) : (
                                <p className="text-sm text-gray-500">No documents uploaded.</p>
                            )}
                        </div>
                    </Card>
                </div>

                {/* Sidebar - Right Column (1/3) */}
                <div className="space-y-6">

                    {/* Risk Assessment */}
                    <Card className="p-6">
                        <div className="flex justify-between items-center mb-4">
                            <h2 className="text-base font-medium text-gray-700 dark:text-gray-200">Risk Assessment</h2>
                            <Button
                                variant="outline"
                                size="sm"
                                className="text-xs h-8"
                                onClick={() => navigate(`/officer/application/${id}/risk`)}
                            >
                                Detailed Analysis
                            </Button>
                        </div>

                        <div className="bg-gray-200 dark:bg-gray-800 p-6 rounded-md text-center mb-6">
                            <p className="text-sm text-gray-500 mb-1">Expected Risk Check</p>
                            {riskSummary ? (
                                <>
                                    <p className={`text-lg font-medium mb-1 font-bold ${riskColors[riskSummary.riskCategory] || 'text-gray-600'}`}>
                                        {riskSummary.riskCategory.replace(' Risk', '').toUpperCase()}
                                    </p>
                                    <p className="text-xs text-gray-500">
                                        Score {riskSummary.overallRiskScore}/100 · Approval {riskSummary.approvalProbability}%
                                    </p>
                                </>
                            ) : (
                                <p className="text-sm text-gray-500">Risk analysis unavailable</p>
                            )}
                        </div>
                    </Card>

                    {/* Decision */}
                    <Card className="p-6">
                        <div className="flex items-center justify-between mb-1">
                            <h2 className="text-base font-medium text-gray-700 dark:text-gray-200">Decision</h2>
                            {app.status !== 'Pending' && (
                                <button
                                    disabled={actionLoading}
                                    onClick={() => handleStatusUpdate('Pending')}
                                    className="text-xs text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 underline disabled:opacity-40 transition-colors"
                                >
                                    Reset to Pending
                                </button>
                            )}
                        </div>

                        {/* Not Eligible Warning Banner */}
                        {app.eligibilityResult?.verdict === 'Not Eligible' && (
                            <div className="flex items-start gap-2 bg-red-50 dark:bg-red-900/20 border border-red-300 dark:border-red-700 rounded-md px-3 py-2 mb-3">
                                <span className="text-red-500 mt-0.5">🚫</span>
                                <div>
                                    <p className="text-xs font-semibold text-red-700 dark:text-red-400">System Eligibility: Not Eligible</p>
                                    <p className="text-xs text-red-600 dark:text-red-400 mt-0.5">This application failed the eligibility assessment. Approval and escalation are blocked. You may only reject this application.</p>
                                </div>
                            </div>
                        )}

                        {/* Invalid Documents Warning Banner */}
                        {app.documents?.some((d: any) => d.status === 'Invalid') && (
                            <div className="flex items-start gap-2 bg-orange-50 dark:bg-orange-900/20 border border-orange-300 dark:border-orange-700 rounded-md px-3 py-2 mb-3">
                                <span className="text-orange-500 mt-0.5">⚠️</span>
                                <div>
                                    <p className="text-xs font-semibold text-orange-700 dark:text-orange-400">Invalid Documents Detected</p>
                                    <p className="text-xs text-orange-600 dark:text-orange-400 mt-0.5">
                                        Invalid: <strong>{app.documents.filter((d: any) => d.status === 'Invalid').map((d: any) => d.fileName).join(', ')}</strong>. Approval and escalation are blocked. Request more info or reject.
                                    </p>
                                </div>
                            </div>
                        )}

                        {app.status !== 'Pending' && (
                            <p className="text-xs text-amber-600 dark:text-amber-400 bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800 rounded-md px-3 py-2 mb-4">
                                ⚠ A decision has been recorded. Other options are locked.
                            </p>
                        )}
                        <div className="space-y-3">
                            {/* Approve / Escalate */}
                            {(() => {
                                const requiresEscalation = app.loanAmount >= 1000000;
                                const isNotEligible = app.eligibilityResult?.verdict === 'Not Eligible';
                                const hasInvalidDocs = app.documents?.some((d: any) => d.status === 'Invalid');
                                const isBlocked = isNotEligible || hasInvalidDocs;
                                const isActive = app.status === 'Approved' || app.status === 'Manager Review';
                                const isLocked = (app.status !== 'Pending' && !isActive) || isBlocked;
                                return (
                                    <button
                                        disabled={actionLoading || isActive || isLocked}
                                        onClick={() => handleStatusUpdate('Approved')}
                                        className={`w-full flex items-center justify-between gap-2 py-3 px-4 rounded-md transition-all text-sm font-medium border-2 ${
                                            isActive
                                                ? 'bg-green-600 border-green-600 text-white ring-2 ring-green-400 ring-offset-2 cursor-default'
                                                : isLocked
                                                ? 'bg-gray-100 dark:bg-gray-800 border-gray-200 dark:border-gray-700 text-gray-400 dark:text-gray-600 cursor-not-allowed'
                                                : 'bg-green-600 border-green-600 text-white hover:bg-green-700 hover:border-green-700'
                                        }`}
                                    >
                                        <span className="flex items-center gap-2">
                                            <CheckCircle className="w-4 h-4" />
                                            {requiresEscalation ? 'Escalate for Approval' : 'Approve Application'}
                                        </span>
                                        {isActive && <span className="text-xs bg-white/20 px-2 py-0.5 rounded-full">Current</span>}
                                        {isBlocked && !isActive && <span className="text-xs">🚫</span>}
                                        {isLocked && !isBlocked && !isActive && <span className="text-xs">🔒</span>}
                                    </button>
                                );
                            })()}

                            {/* Reject */}
                            {(() => {
                                const isActive = app.status === 'Rejected';
                                const isLocked = app.status !== 'Pending' && !isActive;
                                return (
                                    <button
                                        disabled={actionLoading || isActive || isLocked}
                                        onClick={() => handleStatusUpdate('Rejected')}
                                        className={`w-full flex items-center justify-between gap-2 py-3 px-4 rounded-md transition-all text-sm font-medium border-2 ${
                                            isActive
                                                ? 'bg-red-600 border-red-600 text-white ring-2 ring-red-400 ring-offset-2 cursor-default'
                                                : isLocked
                                                ? 'bg-gray-100 dark:bg-gray-800 border-gray-200 dark:border-gray-700 text-gray-400 dark:text-gray-600 cursor-not-allowed'
                                                : 'bg-red-600 border-red-600 text-white hover:bg-red-700 hover:border-red-700'
                                        }`}
                                    >
                                        <span className="flex items-center gap-2">
                                            <XCircle className="w-4 h-4" />
                                            Reject Application
                                        </span>
                                        {isActive && <span className="text-xs bg-white/20 px-2 py-0.5 rounded-full">Current</span>}
                                        {isLocked && <span className="text-xs">🔒</span>}
                                    </button>
                                );
                            })()}

                            {/* Needs Info */}
                            {(() => {
                                const isActive = app.status === 'Needs Info';
                                const isNotEligible = app.eligibilityResult?.verdict === 'Not Eligible';
                                const isLocked = (app.status !== 'Pending' && !isActive) || isNotEligible;
                                return (
                                    <button
                                        disabled={actionLoading || isActive || isLocked}
                                        onClick={() => handleStatusUpdate('Needs Info')}
                                        className={`w-full flex items-center justify-between gap-2 py-3 px-4 rounded-md transition-all text-sm font-medium border-2 ${
                                            isActive
                                                ? 'bg-yellow-500 border-yellow-500 text-white ring-2 ring-yellow-400 ring-offset-2 cursor-default'
                                                : isLocked
                                                ? 'bg-gray-100 dark:bg-gray-800 border-gray-200 dark:border-gray-700 text-gray-400 dark:text-gray-600 cursor-not-allowed'
                                                : 'bg-yellow-500 border-yellow-500 text-white hover:bg-yellow-600 hover:border-yellow-600'
                                        }`}
                                    >
                                        <span className="flex items-center gap-2">
                                            <Info className="w-4 h-4" />
                                            Request More Info
                                        </span>
                                        {isActive && <span className="text-xs bg-white/20 px-2 py-0.5 rounded-full">Current</span>}
                                        {isLocked && <span className="text-xs">🔒</span>}
                                    </button>
                                );
                            })()}
                        </div>
                    </Card>


                    {/* Timeline */}
                    <Card className="p-6">
                        <h2 className="text-base font-medium text-gray-700 dark:text-gray-200 mb-4">Timeline</h2>
                        <div className="relative pl-4 border-l border-gray-200 dark:border-gray-700 space-y-6">
                            <div className="relative">
                                <div className="mb-1">
                                    <p className="text-xs text-gray-500">{new Date(app.createdAt || app.date).toLocaleDateString()}</p>
                                    <p className="text-sm font-medium text-gray-700 dark:text-gray-300">Application Submitted</p>
                                </div>
                            </div>
                            <div className="relative">
                                <div className="mb-1">
                                    <p className="text-xs text-gray-500 text-primary">Current Status</p>
                                    <p className="text-sm font-medium text-gray-700 dark:text-gray-300 capitalize">{app.status}</p>
                                </div>
                            </div>
                        </div>
                    </Card>

                </div>
            </div>
        </div>
    );
};

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Card } from '@/components/ui/Card';
import { Badge } from '@/components/ui/Badge';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Search, Filter, ChevronRight } from 'lucide-react';
import { useToast } from '@/components/ui/Toast';
import { formatNumber } from '@/utils/formatCurrency';

export const ApplicationsList = () => {
    const navigate = useNavigate();
    const { showToast } = useToast();
    const [searchTerm, setSearchTerm] = useState('');
    const [applications, setApplications] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchApps = async () => {
            try {
                const res = await fetch('http://localhost:5000/api/officer/applications');
                if (res.ok) {
                    setApplications(await res.json());
                }
            } catch (err) {
                console.error("Error fetching applications:", err);
            } finally {
                setLoading(false);
            }
        };
        fetchApps();
    }, []);

    const getStatusBadge = (status: string) => {
        switch (status?.toLowerCase()) {
            case 'approved': return 'success';
            case 'manager approved': return 'success';
            case 'rejected': return 'error';
            case 'manager rejected': return 'error';
            case 'manager review': return 'warning';
            case 'needs info': return 'warning';
            case 'pending': return 'info';
            default: return 'info';
        }
    };

    const filteredApplications = applications.filter(app => {
        const search = searchTerm.toLowerCase();
        return (
            app.fullName?.toLowerCase().includes(search) ||
            app.id?.toLowerCase().includes(search) ||
            app.nic?.toLowerCase().includes(search)
        );
    });

    const exportToCSV = () => {
        if (filteredApplications.length === 0) {
            showToast('No data to export', 'warning');
            return;
        }
        const headers = ['Application ID,Applicant,Type,Amount,Date,Status'];
        const csvData = headers.concat(filteredApplications.map(app => 
            `${app.id},"${app.fullName}",${app.loanType},${app.loanAmount},${new Date(app.date || app.createdAt).toLocaleDateString()},${app.status}`
        )).join('\n');
        
        const blob = new Blob([csvData], { type: 'text/csv;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.setAttribute('download', 'loan_applications.csv');
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        showToast('Export triggered successfully', 'success');
    };

    if (loading) return <div className="p-8 text-center text-gray-500 animate-pulse">Loading applications...</div>;

    return (
        <div className="space-y-6 animate-fade-in text-light-text-primary dark:text-dark-text-primary">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <h1 className="text-2xl font-bold">
                    Loan Applications
                </h1>
                <div className="flex gap-2">
                    <Button variant="outline" leftIcon={<Filter className="w-4 h-4" />} onClick={() => showToast('Advanced filtering coming soon!', 'info')}>Filter</Button>
                    <Button onClick={exportToCSV}>Export</Button>
                </div>
            </div>

            <Card className="p-4">
                <div className="mb-4">
                    <Input
                        placeholder="Search by name, ID or NIC..."
                        leftIcon={<Search className="w-4 h-4" />}
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                    />
                </div>

                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left">
                        <thead className="text-xs text-light-text-secondary dark:text-dark-text-secondary uppercase bg-slate-50 dark:bg-slate-800/50">
                            <tr>
                                <th className="px-4 py-3 rounded-l-lg">Application ID</th>
                                <th className="px-4 py-3">Applicant</th>
                                <th className="px-4 py-3">Type</th>
                                <th className="px-4 py-3">Amount</th>
                                <th className="px-4 py-3">Date</th>
                                <th className="px-4 py-3">Risk Level</th>
                                <th className="px-4 py-3">Status</th>
                                <th className="px-4 py-3 rounded-r-lg">Action</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-light-border dark:divide-dark-border">
                            {filteredApplications.map((app) => (
                                <tr key={app.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                                    <td className="px-4 py-3 font-medium text-light-text-primary dark:text-dark-text-primary">{app.id}</td>
                                    <td className="px-4 py-3">{app.fullName}</td>
                                    <td className="px-4 py-3 text-light-text-secondary dark:text-dark-text-secondary">{app.loanType}</td>
                                    <td className="px-4 py-3 font-medium">LKR {formatNumber(app.loanAmount)}</td>
                                    <td className="px-4 py-3 text-light-text-secondary dark:text-dark-text-secondary">
                                        {new Date(app.date || app.createdAt).toLocaleDateString()}
                                    </td>
