                        {pendingTasks.map((task, idx) => (
                            <div key={idx} className="flex gap-3 cursor-pointer hover:bg-slate-50 dark:hover:bg-slate-800/50 p-2 rounded-md transition-colors" onClick={() => navigate(task.link)}>
